import os, re, json, csv, glob
from collections import defaultdict
from xml.etree import ElementTree as ET

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"
files = sorted(glob.glob(ROOT + "/**/*", recursive=True))
files = [f for f in files if os.path.isfile(f)]
print("total files:", len(files))

recs = defaultdict(dict)   # record_id -> {fmt: data}

# --- MD ---
for p in [f for f in files if f.endswith(".md")]:
    t = open(p).read()
    m = re.search(r"RECORD:\s*(CB-DOC-\d+-\d+)", t) or re.search(r"(CB-DOC-\d+-\d+)", t)
    # md has no "RECORD:" line; get from title? Use first CB-DOC occurrence
    rid = re.search(r"(CB-DOC-\d+-\d+)", t).group(1)
    def g(label):
        mm = re.search(r"\|\s*%s\s*\|\s*(.*?)\s*\|" % re.escape(label), t)
        return mm.group(1) if mm else None
    recs[rid]["md"] = {
        "title": t.split("\n")[0].lstrip("# ").strip(),
        "matter": g("Matter"), "pk": g("Portfolio key"), "role": g("Evidence role"),
        "ent": g("Immutable entity"), "ref": g("Referenced revision"), "cur": g("Current revision"),
        "cust": g("Custodian"), "rev": g("Reviewer"), "path": p, "folder": os.path.basename(os.path.dirname(p)),
    }

# --- TXT / EML (same KEY: VALUE pattern) ---
for ext in (".txt", ".eml"):
    for p in [f for f in files if f.endswith(ext)]:
        t = open(p, errors="replace").read()
        rid = re.search(r"(CB-DOC-\d+-\d+)", t).group(1)
        def g2(label):
            mm = re.search(r"^%s:\s*(.*)$" % re.escape(label), t, re.M)
            return mm.group(1).strip() if mm else None
        recs[rid][ext[1:]] = {
            "title": g2("SUBJECT") or (t.split("\n")[2].strip() if len(t.split("\n"))>2 else None),
            "matter": g2("MATTER"), "pk": g2("PORTFOLIO KEY"), "role": g2("EVIDENCE ROLE"),
            "ent": g2("ENTITY KEY"), "ref": g2("REFERENCED REVISION"), "cur": g2("CURRENT REVISION"),
            "cust": g2("CUSTODIAN"), "rev": g2("REVIEWER"), "srcsys": g2("SOURCE SYSTEM"),
            "path": p, "folder": os.path.basename(os.path.dirname(p)),
        }

# --- CSV ---
for p in [f for f in files if f.endswith(".csv")]:
    with open(p) as f:
        rows = list(csv.DictReader(f))
    rid = rows[0]["record_id"]
    meta = {r["key"]: r["value"] for r in rows if r.get("row_type")=="metadata"}
    recs[rid]["csv"] = {"meta": meta,
        "src_rows": [r for r in rows if r.get("row_type")=="source_row"],
        "chron": [r for r in rows if r.get("row_type")=="chronology"],
        "path": p, "folder": os.path.basename(os.path.dirname(p))}

# --- JSON ---
for p in [f for f in files if f.endswith(".json")]:
    d = json.load(open(p))
    recs[d["record_id"]]["json"] = {**d, "path": p, "folder": os.path.basename(os.path.dirname(p))}

# --- XML ---
for p in [f for f in files if f.endswith(".xml")]:
    t = open(p).read()
    rid = re.search(r"(CB-DOC-\d+-\d+)", t).group(1)
    try:
        root = ET.fromstring(t)
        d = {}
        for ch in root:
            if len(ch)==0 and ch.text and ch.text.strip():
                d[ch.tag] = ch.text.strip()
        recs[rid]["xml"] = {**d, "path": p, "folder": os.path.basename(os.path.dirname(p))}
    except Exception as e:
        # fallback regex
        def g3(tag):
            mm = re.search(r"<%s>(.*?)</%s>" % (tag, tag), t, re.S)
            return mm.group(1).strip() if mm else None
        recs[rid]["xml"] = {"pk": g3("portfolio_key"), "role": g3("evidence_role"),
            "ref": g3("referenced_revision"), "cur": g3("current_revision"),
            "path": p, "folder": os.path.basename(os.path.dirname(p))}

# --- HTML ---
for p in [f for f in files if f.endswith(".html")]:
    t = open(p, errors="replace").read()
    rid = re.search(r"(CB-DOC-\d+-\d+)", t).group(1)
    def gh(label):
        mm = re.search(r"<tr>\s*<th[^>]*>%s</th>\s*<td[^>]*>(.*?)</td>" % re.escape(label), t, re.S)
        if mm: return re.sub(r"<[^>]+>","",mm.group(1)).strip()
        return None
    recs[rid]["html"] = {"title": (re.search(r"<h1[^>]*>(.*?)</h1>", t, re.S) or [None,None])[1],
        "pk": gh("Portfolio key"), "role": gh("Evidence role"), "ref": gh("Referenced revision"),
        "cur": gh("Current revision"), "path": p, "folder": os.path.basename(os.path.dirname(p))}

print("distinct record ids:", len(recs))
ids = sorted(recs.keys())
print("first/last:", ids[0], ids[-1])
gaps = [f"CB-DOC-031-{i:03d}" for i in range(1,97) if f"CB-DOC-031-{i:03d}" not in recs]
print("missing ids:", gaps)
fmt_counts = defaultdict(list)
for rid, d in recs.items():
    fmt_counts[tuple(sorted(d.keys()))].append(rid)
for k,v in fmt_counts.items(): print(k, len(v))
json.dump({rid: {f: ({"meta":d["meta"],"n_src":len(d.get("src_rows",[]))} if f=="csv" else {kk:vv for kk,vv in d.items() if not isinstance(vv,(list,dict))}) for f,d in dd.items()} for rid,dd in recs.items()}, open("/tmp/recs_summary.json","w"), indent=1)
