import re, json, glob, os, csv, zlib

ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def pdf_text(path):
    raw = open(path,'rb').read(); texts=[]
    for m in re.finditer(rb"stream\r?\n(.*?)endstream", raw, re.S):
        data=m.group(1)
        try: data=zlib.decompress(data)
        except Exception: pass
        for tm in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*Tj", data):
            s=tm.group(0); s=s[:s.rfind(b")")]; s=s[s.find(b"(")+1:]
            texts.append(s.decode('latin-1'))
        for tm in re.finditer(rb"\[(?:[^\[\]]|\\.)*\]\s*TJ", data):
            parts=re.findall(rb"\((?:\\.|[^\\()])*\)", tm.group(0))
            texts.append("".join(p[1:-1].decode('latin-1') for p in parts))
    return [t.replace("\\(","(").replace("\\)",")") for t in texts]

# Build master: for each file, extract full text + structured fields
master = {}
for p in sorted(glob.glob(ROOT+"/**/*", recursive=True)):
    if not os.path.isfile(p): continue
    ext = os.path.splitext(p)[1].lower()
    rel = os.path.relpath(p, ROOT)
    if ext=='.pdf':
        txt = "\n".join(pdf_text(p))
        d = {}
        for lbl in ["Record","Portfolio key","Evidence role","Immutable entity","Referenced revision","Current revision","Custodian","Reviewer","Source system"]:
            m=re.search(r"^%s:\s*(.*)$"%re.escape(lbl), txt, re.M)
            if m: d[lbl]=m.group(1).strip()
        # native record section
        m=re.search(r"NATIVE RECORD\n(.*?)\n\s*NATIVE RECORD", txt, re.S)
        d["_native"] = re.sub(r"\s+"," ",m.group(1)).strip() if m else None
        # subject from business context
        m=re.search(r"This record concerns (.*?) within Aurora pricing", txt)
        d["_subject"]=m.group(1) if m else None
    elif ext=='.json':
        j=json.load(open(p))
        d={"Record":j["record_id"],"Portfolio key":j["portfolio_key"],"Evidence role":j["evidence_role"],
           "Immutable entity":j["immutable_entity_key"],"Referenced revision":j["referenced_revision"],
           "Current revision":j["current_revision"],"Custodian":j["custodian"],"Reviewer":j["reviewer"],
           "Source system":j["source_system"]}
        sec={s["heading"]:s["text"] for s in j.get("sections",[])}
        d["_native"]=sec.get("Native record"); d["_subject"]=j.get("subject")
        d["_rows"]=j.get("rows"); d["_chron"]=j.get("chronology")
    elif ext=='.csv':
        rows=list(csv.DictReader(open(p)))
        meta={r["key"]:r["value"] for r in rows if r.get("row_type")=="metadata"}
        d={"Record":meta["record_id"] if "record_id" in meta else rows[0]["record_id"],
           "Portfolio key":meta.get("portfolio_key"),"Evidence role":meta.get("evidence_role"),
           "Immutable entity":meta.get("immutable_entity_key"),"Referenced revision":meta.get("referenced_revision"),
           "Current revision":meta.get("current_revision"),"Custodian":meta.get("custodian"),
           "Reviewer":meta.get("reviewer"),"Source system":meta.get("source_system")}
        d["_native"]=meta.get("body"); d["_subject"]=meta.get("subject")
        d["_rows"]=[{k:v for k,v in r.items()} for r in rows if r.get("row_type")=="source_row"]
        d["_chron"]=[r for r in rows if r.get("row_type")=="chronology"]
    elif ext in ('.md','.txt','.eml','.xml','.html'):
        txt=open(p,errors='replace').read()
        d={}
        for lbl,lblu in [("Record","RECORD"),("Matter","MATTER"),("Portfolio key","PORTFOLIO KEY"),
                         ("Evidence role","EVIDENCE ROLE"),("Immutable entity","ENTITY KEY"),
                         ("Referenced revision","REFERENCED REVISION"),("Current revision","CURRENT REVISION"),
                         ("Custodian","CUSTODIAN"),("Reviewer","REVIEWER"),("Source system","SOURCE SYSTEM")]:
            for L in (lbl,lblu):
                m=re.search(r"^%s:\s*(.*)$"%re.escape(L), txt, re.M) or re.search(r"\|\s*%s\s*\|\s*(.*?)\s*\|"%re.escape(L), txt)
                if m: d[lbl]=m.group(1).strip(); break
        if "Record" not in d:
            m=re.search(r"(CB-DOC-031-\d+)", txt); d["Record"]=m.group(1) if m else None
        if "Portfolio key" not in d:
            m=re.search(r"portfolio_key>(.*?)<", txt) or re.search(r"<th[^>]*>Portfolio key</th>\s*<td[^>]*>(.*?)</td>", txt, re.S)
            if m: d["Portfolio key"]=re.sub(r"<[^>]+>","",m.group(1)).strip()
        if "Evidence role" not in d:
            m=re.search(r"evidence_role>(.*?)<", txt) or re.search(r"<th[^>]*>Evidence role</th>\s*<td[^>]*>(.*?)</td>", html_txt:=txt, re.S)
            if m: d["Evidence role"]=re.sub(r"<[^>]+>","",m.group(1)).strip()
        d["_raw"]=txt
    d["_file"]=rel
    master.setdefault(d.get("Record"), {})[ext[1:]]=d

# Consolidate per record
cons = {}
for rid, fmts in master.items():
    best = None
    for f in ("json","csv","pdf","txt","md","eml","xml","html"):
        if f in fmts and fmts[f].get("_native"): best=fmts[f]; break
    if best is None:
        for f in ("json","csv","pdf","txt","md","eml","xml","html"):
            if f in fmts: best=fmts[f]; break
    cons[rid]=best

# Now: group by portfolio key
from collections import defaultdict
bypk = defaultdict(dict)
for rid,d in cons.items():
    if d and d.get("Portfolio key"):
        bypk[d["Portfolio key"]][d.get("Evidence role") or "?"]=d

lines=[]
for pk in sorted(bypk):
    lines.append("="*110)
    lines.append(f"PORTFOLIO {pk}")
    for role in ["identity_crosswalk","operative_authority","current_operations","approval_and_capacity",
                 "correspondence","financial_or_population_support","chronology_and_custody","independent_counterrecord"]:
        d=bypk[pk].get(role)
        if not d: 
            lines.append(f"  [{role}] -- MISSING --"); continue
        lines.append(f"  [{role}] {d['Record']} ({d['_file']}) subj={d.get('_subject')} | ent={d.get('Immutable entity')} ref={d.get('Referenced revision')} cur={d.get('Current revision')} srcsys={d.get('Source system')}")
        if d.get("_native"): lines.append(f"      NATIVE: {d['_native']}")
    lines.append("")
open("/tmp/byportfolio.txt","w").write("\n".join(lines))
print("\n".join(lines[:60]))
print("...")
print("portfolio keys:", sorted(bypk.keys()))
print("counts:", {pk: len(v) for pk,v in sorted(bypk.items())})
"}

