import re, json, glob, os, csv, zlib
from collections import defaultdict
ROOT = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def pdf_text(path):
    raw=open(path,'rb').read(); texts=[]
    for m in re.finditer(rb"stream\r?\n(.*?)endstream", raw, re.S):
        data=m.group(1)
        try: data=zlib.decompress(data)
        except Exception: pass
        for tm in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*Tj", data):
            s=tm.group(0); s=s[:s.rfind(b")")]; s=s[s.find(b"(")+1:]; texts.append(s.decode('latin-1'))
        for tm in re.finditer(rb"\[(?:[^\[\]]|\\.)*\]\s*TJ", data):
            parts=re.findall(rb"\((?:\\.|[^\\()])*\)", tm.group(0))
            texts.append("".join(p[1:-1].decode('latin-1') for p in parts))
    return "\n".join(t.replace("\\(","(").replace("\\)",")") for t in texts)

# Load everything as text with fields
recdata=defaultdict(lambda: defaultdict(dict))   # rid -> fmt -> fields
for p in sorted(glob.glob(ROOT+"/**/*", recursive=True)):
    if not os.path.isfile(p): continue
    ext=os.path.splitext(p)[1].lower(); rel=os.path.relpath(p,ROOT)
    if ext=='.pdf': txt=pdf_text(p)
    elif ext=='.json': txt=json.dumps(json.load(open(p)))
    elif ext=='.xlsx': continue
    else: txt=open(p,errors='replace').read()
    f={}
    rid=re.search(r"(CB-DOC-031-\d+)", txt).group(1)
    for lbl in ["Record","Matter","Portfolio key","Evidence role","Immutable entity","Referenced revision","Current revision","Custodian","Reviewer","Source system"]:
        m=(re.search(r"^%s:\s*(.*)$"%re.escape(lbl), txt, re.M)
           or re.search(r"\|\s*%s\s*\|\s*(.*?)\s*\|"%re.escape(lbl), txt)
           or re.search(r"<%s>(.*?)</%s>"%(re.escape(lbl.lower().replace(' ','_')),re.escape(lbl.lower().replace(' ','_'))), txt)
           or re.search(r"<th[^>]*>\s*%s\s*</th>\s*<td[^>]*>(.*?)</td>"%re.escape(lbl), txt, re.S)
           or re.search(r'"%s":\s*"([^"]*)"'%re.escape(lbl.lower().replace(' ','_')), txt))
        if m: f[lbl]=re.sub(r"\s+"," ",re.sub(r"<[^>]+>","",m.group(1))).strip()
    m=re.search(r"This record concerns (.*?) within Aurora pricing", txt)
    if m: f["Subject"]=m.group(1)
    f["_file"]=rel; f["_ext"]=ext[1:]
    recdata[rid][ext[1:]]=f

# merge: prefer richest
allrec={}
for rid,fmts in recdata.items():
    merged={}
    for fmt in ["json","csv","pdf","txt","md","eml","xml","html"]:
        if fmt in fmts:
            for k,v in fmts[fmt].items():
                if v and (k not in merged or merged[k] in (None,"")): merged[k]=v
    allrec[rid]=merged
print("total records:", len(allrec))

bypk=defaultdict(list)
for rid,f in allrec.items():
    bypk[f.get("Portfolio key","?")].append((rid,f))
print("portfolios:", sorted(bypk.keys()))

# subject per portfolio
subj={}
for pk,lst in bypk.items():
    s=set(f.get("Subject") for _,f in lst if f.get("Subject"))
    subj[pk]=s
    print(pk, "| n_records:", len(lst), "| subjects:", s, "| entity:", set(f.get("Immutable entity") for _,f in lst if f.get("Immutable entity")))
json.dump({rid:f for rid,f in allrec.items()}, open("/tmp/allrec.json","w"), indent=1, default=str)
"}

